SELECT toString(properties.app_version) AS Version,uniqExactIf(properties.operation_id,event='native_export_started') AS Started,uniqExactIf(properties.operation_id,event='native_export_completed') AS Completed,uniqExactIf(properties.operation_id,event='native_export_failed') AS Failed,uniqExactIf(properties.operation_id,event='native_export_canceled') AS Canceled FROM events WHERE event IN ('native_export_started','native_export_completed','native_export_failed','native_export_canceled') AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY Version ORDER BY Started DESC LIMIT 30
